INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','easy','flashcard','What are the three irreversible (regulatory) steps of glycolysis?','["Hexokinase (glucose to G6P), Phosphofructokinase-1 (F6P to F1,6-BP), Pyruvate kinase (PEP to pyruvate)"]','A','Mnemonic: HiPPo. These three steps are bypassed during gluconeogenesis by alternative enzymes (G6Pase, F1,6-BPase, PEPCK/PC).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','easy','flashcard','What is the net ATP yield from one glucose molecule undergoing anaerobic glycolysis?','["2 ATP net, plus 2 NADH and 2 pyruvate"]','A','Glycolysis uses 2 ATP (priming) and produces 4 ATP (substrate-level phosphorylation), giving net 2 ATP. In anaerobic conditions, NADH is reoxidised by converting pyruvate to lactate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','flashcard','What are the products of one turn of the TCA cycle starting from acetyl-CoA?','["2 CO2, 3 NADH, 1 FADH2, 1 GTP (substrate-level phosphorylation)"]','A','The TCA cycle produces reducing equivalents (NADH, FADH2) that feed into the electron transport chain to generate ~10 ATP per acetyl-CoA via oxidative phosphorylation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','flashcard','Which enzyme commits fructose-6-phosphate to glycolysis and is the primary regulatory enzyme of the pathway?','["Phosphofructokinase-1 (PFK-1)"]','A','PFK-1 is allosterically inhibited by ATP and citrate (energy surplus) and activated by AMP and fructose-2,6-bisphosphate. Insulin raises F2,6-BP levels promoting glycolysis; glucagon lowers F2,6-BP.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','flashcard','What are the key gluconeogenic precursors and where does gluconeogenesis primarily occur?','["Lactate, alanine, glutamine, glycerol, and propionate; occurs mainly in the liver and to a lesser extent the kidney cortex"]','A','The Cori cycle shuttles lactate from muscle to liver for gluconeogenesis. Alanine from muscle is the predominant amino acid gluconeogenic precursor (glucose-alanine cycle).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','flashcard','What is the role of glycogen phosphorylase in glycogen breakdown?','["Glycogen phosphorylase cleaves alpha-1,4-glycosidic bonds from the non-reducing end of glycogen using inorganic phosphate, releasing glucose-1-phosphate"]','A','Glycogen phosphorylase is activated by glucagon (via cAMP/PKA cascade) and epinephrine in liver, and by epinephrine and AMP in muscle. It stops 4 residues from a branch point; debranching enzyme handles alpha-1,6 bonds.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','medium','flashcard','What are the two main products of the pentose phosphate pathway and their functions?','["NADPH (for reductive biosynthesis and antioxidant defence) and ribose-5-phosphate (for nucleotide synthesis)"]','A','NADPH maintains glutathione in the reduced state (GSH), protecting erythrocytes from oxidative damage. G6PD deficiency impairs the pentose phosphate pathway, causing haemolytic anaemia with oxidant drugs such as primaquine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','hard','flashcard','What is the Pasteur effect?','["Inhibition of glycolysis by oxygen; in aerobic conditions, oxidative phosphorylation produces abundant ATP, which allosterically inhibits PFK-1 and hexokinase, reducing glycolytic flux"]','A','Contrast with the Warburg effect: tumour cells favour aerobic glycolysis even in the presence of oxygen, generating lactate despite sufficient O2 due to upregulated glucose transporters and altered PFK-1 isoforms.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','hard','flashcard','Why can acetyl-CoA not be a net source of glucose in humans?','["The pyruvate dehydrogenase reaction is irreversible, and the two carbons entering the TCA cycle as acetyl-CoA are lost as CO2 before oxaloacetate is regenerated; there is no net carbon gain for gluconeogenesis"]','A','This is why fat (yielding acetyl-CoA via beta-oxidation) cannot make net glucose. However, the glycerol backbone of triglycerides CAN enter gluconeogenesis. Odd-chain fatty acids yield propionyl-CoA which can enter the TCA cycle as succinyl-CoA.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Carbohydrate Metabolism','hard','flashcard','What is the role of pyruvate dehydrogenase complex (PDHC) and how is it regulated?','["PDHC irreversibly converts pyruvate to acetyl-CoA + CO2 + NADH. It is inhibited by its products (acetyl-CoA, NADH, ATP) and by PDH kinase; activated by PDH phosphatase (stimulated by Ca2+ and insulin)"]','A','PDHC requires five cofactors: TPP (B1), lipoic acid, CoA (B5), FAD (B2), NAD+ (B3). Deficiency of PDH, often due to thiamine deficiency, causes lactic acidosis and neurological symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','easy','flashcard','What is the committed step of fatty acid synthesis and which enzyme catalyses it?','["Acetyl-CoA to malonyl-CoA, catalysed by acetyl-CoA carboxylase (ACC)"]','A','ACC is activated by citrate (energy surplus) and inhibited by palmitoyl-CoA (feedback) and glucagon (via phosphorylation). Insulin activates it via dephosphorylation. Biotin (B7) is the cofactor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','easy','flashcard','What are the products of complete beta-oxidation of palmitoyl-CoA (C16:0)?','["7 cycles of beta-oxidation yield 8 acetyl-CoA, 7 NADH, and 7 FADH2"]','A','Each cycle of beta-oxidation produces 1 acetyl-CoA, 1 NADH, and 1 FADH2. The 8 acetyl-CoA enter the TCA cycle. Net ATP yield is approximately 106 ATP from one palmitate after subtracting 2 ATP for activation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','easy','flashcard','Where does fatty acid synthesis take place in the cell, and what is the main NADPH source?','["Cytosol; NADPH is primarily supplied by the pentose phosphate pathway and the malic enzyme reaction"]','A','Contrast with beta-oxidation, which occurs in the mitochondrial matrix. Acetyl-CoA must be exported from mitochondria as citrate (citrate shuttle) to reach the cytosol for fatty acid synthesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','flashcard','What is the rate-limiting step of ketogenesis and where does it occur?','["HMG-CoA synthase (mitochondrial) in hepatocyte mitochondria; ketone bodies (acetoacetate, beta-hydroxybutyrate, acetone) are produced when acetyl-CoA exceeds TCA capacity"]','A','Ketogenesis increases in starvation, diabetic ketoacidosis, and prolonged exercise. Ketone bodies are exported to extrahepatic tissues (brain, muscle) but the liver cannot use them as it lacks succinyl-CoA transferase (thiophorase).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','flashcard','What is the function of carnitine in fatty acid metabolism?','["Carnitine shuttles long-chain fatty acyl groups across the inner mitochondrial membrane via carnitine acyltransferase I (CAT-I, outer membrane) and CAT-II (inner membrane)"]','A','CAT-I is the rate-limiting step of beta-oxidation; it is inhibited by malonyl-CoA, ensuring that fatty acid synthesis and oxidation do not occur simultaneously. Medium/short-chain fatty acids do not need carnitine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','flashcard','What are the five major lipoprotein classes and their functions?','["Chylomicrons (dietary fat from gut), VLDL (endogenous TG from liver), IDL (VLDL remnant), LDL (cholesterol to tissues), HDL (reverse cholesterol transport from tissues to liver)"]','A','Apolipoproteins determine lipoprotein function: ApoB-48 (chylomicrons), ApoB-100 (VLDL/LDL), ApoA-I (HDL), ApoC-II (activates lipoprotein lipase), ApoE (receptor-mediated uptake).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','flashcard','What is the rate-limiting enzyme of cholesterol synthesis and how is it regulated?','["HMG-CoA reductase (converts HMG-CoA to mevalonate); inhibited by statins, cholesterol (via SREBP), and glucagon; activated by insulin"]','A','Statins (e.g., atorvastatin) competitively inhibit HMG-CoA reductase, reducing LDL cholesterol. Cholesterol inhibits its own synthesis via SREBP-2 transcription factor. Synthesis is highest at night.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','medium','flashcard','How does fatty acid oxidation differ for unsaturated fatty acids?','["Unsaturated fatty acids require additional enzymes: enoyl-CoA isomerase (for odd-positioned double bonds) and 2,4-dienoyl-CoA reductase (for even-positioned double bonds), yielding slightly less ATP than saturated equivalents"]','A','Fewer FADH2 are produced because double bonds at even carbons bypass the acyl-CoA dehydrogenase step (which generates FADH2). For example, oleate (C18:1) yields 2 fewer ATP than stearate (C18:0).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','hard','flashcard','What is the difference between type I and type II fatty acid synthase (FAS) systems?','["Type I FAS (mammals): single multifunctional polypeptide homodimer with all enzymatic activities. Type II FAS (bacteria, mitochondria): separate discrete enzymes for each step, the basis for antibiotic selectivity"]','A','The type II FAS in bacteria is exploited as an antibiotic target (e.g., triclosan inhibits enoyl-ACP reductase). The mammalian mitochondria also use type II FAS for synthesis of octanoyl chains as the lipoic acid precursor.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Lipid Metabolism','hard','flashcard','What is Refsum disease and what is its biochemical basis?','["Autosomal recessive disorder caused by deficiency of phytanoyl-CoA hydroxylase, leading to accumulation of phytanic acid (a branched-chain fatty acid from dietary chlorophyll) because it cannot undergo standard beta-oxidation"]','A','Phytanic acid undergoes alpha-oxidation due to its 3-methyl branch. Features: peripheral neuropathy, cerebellar ataxia, retinitis pigmentosa, anosmia. Treatment: restrict dairy and ruminant meat.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','easy','flashcard','What are the essential amino acids that must be obtained from the diet?','["PVT TIM HaLL: Phenylalanine, Valine, Threonine, Tryptophan, Isoleucine, Methionine, Histidine (conditionally), Arginine (conditionally), Leucine, Lysine"]','A','Mnemonic: PVT TIM HaLL. Histidine and arginine are conditionally essential (required during growth or illness). All others can be synthesised by the human body.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','easy','flashcard','What is transamination and which coenzyme is required?','["Transfer of an amino group from an amino acid to an alpha-keto acid, producing a new amino acid and a new alpha-keto acid; requires pyridoxal phosphate (PLP, vitamin B6) as cofactor"]','A','Key transaminases: ALT (alanine + alpha-KG to pyruvate + glutamate) and AST (aspartate + alpha-KG to OAA + glutamate). Elevated serum ALT/AST indicates hepatocellular damage. PLP is always the cofactor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','flashcard','What are the five steps of the urea cycle and where do the two nitrogen atoms in urea originate?','["Step 1: NH4+ + CO2 to carbamoyl phosphate (CPS-I, mitochondria). Steps 2-5 incorporate aspartate nitrogen. One N comes from free NH4+ (via glutamate dehydrogenase), one N from aspartate. Urea is released and ornithine is regenerated."]','A','CPS-I is activated by N-acetylglutamate (NAG). Urea cycle disorders cause hyperammonaemia; the commonest is OTC deficiency (X-linked). High ammonia is neurotoxic (inhibits alpha-KG conversion to glutamate, depleting TCA intermediates).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','flashcard','What is the difference between glucogenic and ketogenic amino acids?','["Glucogenic AAs are degraded to TCA intermediates or pyruvate and can be used for gluconeogenesis. Ketogenic AAs are degraded to acetyl-CoA or acetoacetyl-CoA and can form ketone bodies but not net glucose."]','A','Purely ketogenic: Leucine and Lysine (mnemonic: LeucKine). Both glucogenic and ketogenic: Ile, Phe, Trp, Tyr, Thr. All others are purely glucogenic. Fat (acetyl-CoA) cannot make net glucose.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','flashcard','What is the role of glutamate dehydrogenase (GDH) in nitrogen metabolism?','["GDH catalyses the oxidative deamination of glutamate to alpha-ketoglutarate + NH4+, releasing free ammonia for the urea cycle; it uses NAD+ or NADP+ and is activated by ADP and inhibited by GTP and NADH"]','A','GDH sits at the junction of amino acid catabolism and the TCA cycle. Hyperinsulinism-hyperammonaemia syndrome results from gain-of-function GDH mutations (loss of GTP inhibition), causing excess ammonia production.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','flashcard','What are the four levels of protein structure?','["Primary (amino acid sequence/peptide bonds), Secondary (alpha-helix, beta-sheet stabilised by backbone H-bonds), Tertiary (3D fold: H-bonds, disulfide bonds, hydrophobic interactions, ionic bonds), Quaternary (multiple subunit assembly)"]','A','Denaturation disrupts secondary through quaternary structure but not primary structure (peptide bonds remain intact). Chaperones (Hsp70, Hsp90) assist proper folding; misfolding leads to prion diseases, Alzheimer disease, and other proteinopathies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','medium','flashcard','Which amino acid is the major inter-organ nitrogen carrier from muscle to liver?','["Alanine (glucose-alanine cycle): muscle transamination of pyruvate + glutamate yields alanine, which is transported to the liver for gluconeogenesis and urea synthesis"]','A','Glutamine is also a major nitrogen carrier, especially to the kidney and gut. In the kidney, glutamine releases NH4+ into urine (important for acid-base balance). Alanine carbon skeleton becomes glucose in the liver.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','hard','flashcard','What is the biochemical defect in classical homocystinuria and what are its clinical features?','["Deficiency of cystathionine beta-synthase (CBS; requires PLP/B6), causing accumulation of homocysteine and methionine. Features: Marfan-like habitus, ectopia lentis (downward), intellectual disability, thromboembolism, premature atherosclerosis"]','A','Contrast with Marfan syndrome: ectopia lentis is upward in Marfan, downward in homocystinuria. Treatment: pyridoxine (B6) if responsive, methionine restriction, betaine, folate and B12. Elevated homocysteine is a cardiovascular risk factor.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','hard','flashcard','What is the ubiquitin-proteasome pathway?','["A system for selective intracellular protein degradation: ubiquitin molecules are covalently attached (polyubiquitinated) to target proteins, which are then recognised and degraded by the 26S proteasome into peptides"]','A','The pathway requires E1 (ubiquitin-activating), E2 (ubiquitin-conjugating), and E3 (ubiquitin ligase, provides substrate specificity) enzymes. Dysregulation is implicated in cancer. Bortezomib (proteasome inhibitor) is used in multiple myeloma.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Amino Acid & Protein Metabolism','hard','flashcard','What are the catecholamine biosynthetic steps from tyrosine and which cofactors are required?','["Tyrosine to DOPA (tyrosine hydroxylase, BH4) to dopamine (DOPA decarboxylase, PLP) to norepinephrine (dopamine beta-hydroxylase, vitamin C + Cu2+) to epinephrine (PNMT, SAM as methyl donor)"]','A','Rate-limiting step: tyrosine hydroxylase (inhibited by catecholamines via end-product inhibition). BH4 (tetrahydrobiopterin) deficiency causes a form of PKU with catecholamine and serotonin deficiency. PNMT is induced by cortisol.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','easy','flashcard','What does Km represent in Michaelis-Menten kinetics?','["Km is the substrate concentration at which reaction velocity equals half of Vmax; it reflects the affinity of an enzyme for its substrate — a low Km means high affinity"]','A','Vmax is the maximum reaction velocity at saturating substrate. The Michaelis-Menten equation: v = (Vmax x [S]) / (Km + [S]). A Lineweaver-Burk (double-reciprocal) plot gives x-intercept = -1/Km and y-intercept = 1/Vmax.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','easy','flashcard','How does competitive inhibition differ from non-competitive inhibition in terms of Km and Vmax?','["Competitive: Km increases (apparent), Vmax unchanged. Non-competitive: Vmax decreases, Km unchanged (inhibitor binds a site other than the active site, reducing catalytic efficiency)"]','A','Competitive inhibition can be overcome by increasing substrate concentration. Non-competitive inhibitors bind enzyme-substrate complex or free enzyme equally; increasing substrate does not overcome inhibition.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','easy','flashcard','What mechanisms do cells use to regulate enzyme activity?','["Allosteric regulation (effector binding changes enzyme conformation), covalent modification (phosphorylation/dephosphorylation), proteolytic activation (zymogens), gene expression changes, and substrate/product availability"]','A','Phosphorylation is the most common covalent modification. PKA (activated by cAMP/glucagon) phosphorylates many metabolic enzymes. Zymogens (e.g., pepsinogen, trypsinogen) prevent autodigestion and are activated by cleavage at the site of action.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','flashcard','What is the significance of a sigmoidal (cooperative) enzyme kinetics curve compared to a hyperbolic (Michaelis-Menten) curve?','["Sigmoidal kinetics indicate cooperative binding (e.g., haemoglobin, allosteric enzymes like ATCase). Binding of one substrate molecule increases affinity for subsequent molecules (positive cooperativity), allowing more sensitive regulation around a threshold substrate concentration"]','A','Hill coefficient (nH) > 1 indicates positive cooperativity. Allosteric enzymes like PFK-1 and ATCase show sigmoidal kinetics. Haemoglobin O2 binding is sigmoidal with nH approximately 2.8. Not described by simple Michaelis-Menten kinetics.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','flashcard','What is the role of thiamine pyrophosphate (TPP) as a cofactor?','["TPP (active form of vitamin B1) is required for oxidative decarboxylation of alpha-keto acids: pyruvate dehydrogenase complex (pyruvate to acetyl-CoA), alpha-ketoglutarate dehydrogenase (TCA cycle), and branched-chain alpha-keto acid dehydrogenase (BCAA catabolism)"]','A','Thiamine deficiency impairs all three reactions, causing pyruvate and lactate accumulation. Clinical syndromes: Wernicke encephalopathy (confusion, ophthalmoplegia, ataxia), Korsakoff psychosis, beriberi (wet = cardiac, dry = neurological).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','flashcard','What is the function of NAD+ and NADP+ as enzyme cofactors?','["NAD+ (derived from niacin/B3) accepts electrons in catabolic reactions (glycolysis, TCA, beta-oxidation) to form NADH, which donates electrons to Complex I of the ETC. NADPH (from PPP and malic enzyme) donates electrons in anabolic reactions and antioxidant defence"]','A','NAD+ is predominantly catabolic; NADPH is anabolic. NADPH maintains glutathione reduced (GSH) for ROS scavenging. Pellagra (niacin deficiency): dermatitis, diarrhoea, dementia (3 Ds). Tryptophan can be converted to niacin at a 60:1 ratio.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','flashcard','What is the difference between a coenzyme and a prosthetic group?','["Coenzymes are loosely (non-covalently) associated organic cofactors that can dissociate from the enzyme (e.g., NAD+, CoA); prosthetic groups are tightly (often covalently) bound and remain associated with the enzyme (e.g., FAD in succinate dehydrogenase, haem in cytochrome c oxidase)"]','A','Cofactor is the general term for non-protein helper molecules including metal ions. Coenzyme is an organic cofactor. Many vitamins function as coenzymes or prosthetic groups (e.g., PLP, FAD, FMN, CoA, TPP, biotin).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','medium','flashcard','What is kcat and what does the kcat/Km ratio represent?','["kcat (turnover number) = maximum number of substrate molecules converted per enzyme molecule per second at saturating substrate. kcat/Km = catalytic efficiency, measuring how effectively an enzyme works at low (non-saturating) substrate concentrations"]','A','The theoretical upper limit of kcat/Km is approximately 10^8-10^9 M-1s-1 (diffusion limit). Enzymes approaching this are called catalytically perfect (e.g., carbonic anhydrase, acetylcholinesterase, triosephosphate isomerase).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','hard','flashcard','What distinguishes uncompetitive inhibition from mixed inhibition?','["Uncompetitive: inhibitor binds only the enzyme-substrate (ES) complex, so both Km and Vmax decrease proportionally (Vmax/Km ratio unchanged). Mixed inhibition: inhibitor binds both free enzyme and ES complex, Vmax decreases and Km may increase or decrease"]','A','Uncompetitive inhibitors are uncommon but clinically relevant: lithium inhibits inositol phosphatase by an uncompetitive mechanism. On a Lineweaver-Burk plot, uncompetitive inhibition gives parallel lines (same slope); mixed inhibition gives lines intersecting to the left of the y-axis.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Enzyme Kinetics & Cofactors','hard','flashcard','What is the role of biotin as an enzyme cofactor and which enzymes require it?','["Biotin (B7) acts as a CO2 carrier in carboxylation reactions. Key biotin-dependent enzymes: pyruvate carboxylase (pyruvate to OAA), acetyl-CoA carboxylase (acetyl-CoA to malonyl-CoA), propionyl-CoA carboxylase, methylcrotonyl-CoA carboxylase"]','A','Biotin is covalently attached to the enzyme via a lysine residue. Avidin in raw egg whites binds biotin tightly causing deficiency. Biotin deficiency: dermatitis, alopecia, neurological symptoms. Biotinidase deficiency (neonatal) is a treatable cause of metabolic disease.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','easy','flashcard','Which vitamins are fat-soluble and what are the consequences of toxicity?','["Fat-soluble vitamins: A, D, E, K (mnemonic: ADEK). Stored in adipose and liver; can accumulate to toxic levels. Vitamin A toxicity: teratogenicity, hepatotoxicity, raised ICP. Vitamin D toxicity: hypercalcaemia."]','A','Water-soluble vitamins (B-complex, C) are generally not toxic as excess is excreted in urine. Exceptions: B6 excess causes peripheral neuropathy; niacin excess causes flushing and hepatotoxicity. ADEK accumulate with supplement megadosing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','easy','flashcard','What disease is caused by vitamin C (ascorbic acid) deficiency and what is the biochemical basis?','["Scurvy. Vitamin C is required for hydroxylation of proline and lysine residues in collagen synthesis (cofactor for prolyl and lysyl hydroxylases). Deficiency leads to defective collagen, causing perifollicular haemorrhages, corkscrew hairs, bleeding gums, and poor wound healing"]','A','Vitamin C also maintains Fe2+ for iron absorption and is an antioxidant. Scurvy features mnemonic: SCAN - Spongy gums, Corkscrew hairs, Anaemia, No wound healing. Also haemarthroses and subperiosteal haemorrhages.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','easy','flashcard','What is vitamin A (retinol) and what are the clinical consequences of its deficiency?','["Vitamin A (retinol, retinal, retinoic acid) is essential for vision (retinal as 11-cis-retinal in rhodopsin), cell differentiation, immune function, and reproduction. Deficiency: night blindness (first sign), Bitot spots, xerophthalmia, keratomalacia, increased susceptibility to infection"]','A','Retinoic acid binds nuclear RAR/RXR receptors to regulate gene transcription. Hypervitaminosis A: teratogenic (isotretinoin for acne is contraindicated in pregnancy), hepatotoxicity, pseudotumour cerebri. Beta-carotene (provitamin A) from plants is non-toxic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','flashcard','What are the functions of vitamin D and what happens in its deficiency?','["Vitamin D3 (cholecalciferol) is hydroxylated in the liver (25-hydroxylation) then kidney (1-alpha-hydroxylation) to active 1,25-(OH)2D3 (calcitriol). It promotes intestinal Ca2+ and phosphate absorption and bone mineralisation. Deficiency: rickets (children), osteomalacia (adults)"]','A','25-hydroxylation in liver is substrate-driven; 1-alpha-hydroxylation in kidney is regulated by PTH (increases it) and FGF-23 (inhibits it). Calcitriol acts as a steroid hormone via nuclear VDR receptors. Dietary sources plus sunlight (UVB converts 7-dehydrocholesterol to vitamin D3).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','flashcard','What is the role of vitamin K and which clotting factors does it affect?','["Vitamin K is required for gamma-carboxylation of glutamate residues on clotting factors II, VII, IX, X (and protein C and S), enabling them to bind Ca2+ and phospholipid surfaces. Deficiency prolongs PT (and PTT); warfarin antagonises vitamin K epoxide reductase"]','A','Mnemonic: 1972 - factors II, VII, IX, X require vitamin K. Neonates are at risk (sterile gut, poor placental transfer) so prophylactic vitamin K is given at birth. Warfarin overdose treated with vitamin K (slow) or FFP/PCC (fast reversal).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','flashcard','What is the biochemical role of folate (B9) and what are the consequences of deficiency?','["Folate (as tetrahydrofolate, THF) carries and transfers one-carbon units for purine synthesis, thymidylate synthesis (dUMP to dTMP via thymidylate synthase), and amino acid interconversions. Deficiency: megaloblastic anaemia, neural tube defects"]','A','Methotrexate and trimethoprim inhibit dihydrofolate reductase (DHFR), blocking THF regeneration. Folate supplementation (400 mcg/day) is essential periconceptionally to prevent neural tube defects. B12 deficiency causes a folate trap (methyl-THF cannot be used) - distinguished from folate deficiency by neurological features (subacute combined degeneration of the cord in B12 deficiency).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','flashcard','What is the function of vitamin B12 (cobalamin) and what are the clinical features of deficiency?','["B12 is required for two reactions: (1) methionine synthase (homocysteine to methionine, requires methylcobalamin) and (2) methylmalonyl-CoA mutase (methylmalonyl-CoA to succinyl-CoA, requires adenosylcobalamin). Deficiency: megaloblastic anaemia, subacute combined degeneration of the spinal cord, elevated MMA and homocysteine"]','A','Causes of B12 deficiency: pernicious anaemia (anti-intrinsic factor antibodies), veganism, gastrectomy, Crohn disease (terminal ileum). Intrinsic factor (IF) from parietal cells is required for B12 absorption. Subacute combined degeneration: posterior (vibration/proprioception) and lateral (UMN signs) columns.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','medium','flashcard','What are the roles of iron in the body and what are the features of iron deficiency?','["Iron is a component of haemoglobin, myoglobin, cytochromes (ETC), and many enzymes. Deficiency (most common nutritional deficiency worldwide): microcytic hypochromic anaemia, koilonychia (spoon nails), glossitis, pica, Plummer-Vinson syndrome (dysphagia + anaemia + oesophageal webs)"]','A','Dietary haem iron (Fe2+) is absorbed better than non-haem iron (Fe3+, reduced by vitamin C). Stored as ferritin; transported by transferrin. Serum ferritin is the best indicator of iron stores. HFE mutations lead to hereditary haemochromatosis (iron overload, bronze diabetes).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','hard','flashcard','What are the clinical syndromes of niacin (vitamin B3) deficiency and how is niacin metabolism related to tryptophan?','["Pellagra: 4 Ds - Dermatitis (sun-exposed areas, Casal necklace), Diarrhoea, Dementia, Death. Tryptophan is a niacin precursor (60 mg tryptophan to 1 mg niacin). Deficiency in Hartnup disease (tryptophan malabsorption) and carcinoid syndrome (tryptophan diverted to serotonin) can cause pellagra"]','A','Niacin is used pharmacologically (high dose) to raise HDL and lower VLDL/triglycerides (inhibits VLDL secretion from liver). Side effect: flushing (mediated by prostaglandins, reduced by aspirin). Also used to treat familial hypercholesterolaemia.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Vitamins & Minerals','hard','flashcard','What is the role of zinc in biochemistry and what are the consequences of deficiency?','["Zinc is a structural and catalytic cofactor in more than 300 enzymes (e.g., carbonic anhydrase, alkaline phosphatase, alcohol dehydrogenase, DNA/RNA polymerases, matrix metalloproteinases). Deficiency: growth retardation, hypogonadism, acrodermatitis enteropathica (perioral/periorbital rash), poor wound healing, anosmia, dysgeusia, immune dysfunction"]','A','Acrodermatitis enteropathica is an autosomal recessive disorder of zinc absorption (SLC39A4 mutation). Zinc also forms zinc finger motifs in transcription factors. Excess zinc impairs copper absorption (competitive). High-dose zinc is used in Wilson disease to reduce copper absorption.','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','easy','flashcard','What are the key structural features of the DNA double helix (Watson-Crick model)?','["Two antiparallel polynucleotide strands wound in a right-handed double helix; bases pair via H-bonds: A=T (2 H-bonds), G=C (3 H-bonds); sugar-phosphate backbone on outside; base pairs on inside; one complete turn per 10 bp (3.4 nm pitch)"]','A','Higher G=C content means higher melting temperature (Tm). The major groove (wider) is the site of sequence-specific protein binding. Minor groove is narrower. B-form DNA is the most common physiological form.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','easy','flashcard','What is the Chargaff rule and why is it important?','["In any double-stranded DNA, the molar amount of adenine equals thymine (A=T) and guanine equals cytosine (G=C). Therefore %A + %G = %T + %C = 50%. This underpinned the Watson-Crick base-pairing model."]','A','Chargaff rules apply to double-stranded DNA only. In single-stranded DNA or RNA there is no requirement for A=U or G=C. GC content varies between species and correlates with melting temperature and DNA stability.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','flashcard','What are the key enzymes involved in DNA replication and their functions?','["Helicase (unwinds double helix), primase (synthesises RNA primer), DNA polymerase III (main prokaryotic replication enzyme, 5-to-3 synthesis + 3-to-5 proofreading exonuclease), DNA polymerase I (removes RNA primers, fills gaps), DNA ligase (seals nicks), SSBs (stabilise single strands), topoisomerase (relieves supercoiling)"]','A','In eukaryotes: Pol alpha (primase activity), Pol delta (lagging strand + PCNA), Pol epsilon (leading strand). PCNA is the sliding clamp. RPA is the SSB. Replication is bidirectional from multiple origins. Telomerase maintains telomeres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','flashcard','What is the role of DNA topoisomerases and which antibiotics/drugs target them?','["Topoisomerases relieve torsional stress during DNA replication and transcription. Type I: cuts one strand. Type II: cuts both strands. Bacterial topoisomerase II (gyrase) is inhibited by fluoroquinolones; eukaryotic topoisomerases are inhibited by camptothecin (Type I) and etoposide (Type II)"]','A','Fluoroquinolones (e.g., ciprofloxacin) inhibit DNA gyrase and topoisomerase IV, preventing DNA re-ligation and causing double-strand breaks and bacterial death. Irinotecan (anticancer) inhibits human topoisomerase I.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','flashcard','What are the major DNA repair mechanisms and the diseases associated with their defects?','["NER (nucleotide excision repair) - bulky adducts, UV-induced pyrimidine dimers; defect: xeroderma pigmentosum. MMR (mismatch repair) - replication errors; defect: Lynch syndrome. BER (base excision repair) - small base damage. DSBR - NHEJ and homologous recombination; defect: BRCA1/2 mutations (breast/ovarian cancer)"]','A','Xeroderma pigmentosum: extreme UV sensitivity, greatly increased skin cancer risk. Lynch syndrome: hereditary non-polyposis colorectal cancer (HNPCC) due to MLH1, MSH2, etc. PARP inhibitors (olaparib) exploit synthetic lethality in BRCA-deficient tumours.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','flashcard','What is the difference between a transition and a transversion mutation?','["Transition: substitution of a purine for a purine (A to G) or a pyrimidine for a pyrimidine (C to T) - same class. Transversion: substitution of a purine for a pyrimidine or vice versa - class change. Transitions are more common."]','A','Transitions are more frequent because base-pair geometry is conserved. Specific mutagens cause characteristic mutation signatures: UV causes C-to-T transitions at pyrimidine dimers; alkylating agents cause G-to-A transitions; aflatoxin causes G-to-T transversions (hepatocellular carcinoma).','universal',false,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','medium','flashcard','What are telomeres and what is the role of telomerase?','["Telomeres are repetitive DNA sequences (TTAGGG in humans) at chromosome ends that protect against the end-replication problem (shortening at each division). Telomerase is a ribonucleoprotein reverse transcriptase that uses its RNA template to extend telomeres; active in germline, stem cells, and cancer cells"]','A','Each cell division shortens telomeres by 50-200 bp. When critically short, cells enter senescence or apoptosis (Hayflick limit). Telomerase is upregulated in approximately 85% of cancers (immortalisation). Dyskeratosis congenita is a telomere maintenance disorder.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','hard','flashcard','What is the mechanism of action of alkylating agents used in chemotherapy and how do cells repair alkylation damage?','["Alkylating agents (e.g., cyclophosphamide, nitrogen mustards) add alkyl groups to DNA bases, predominantly at N7 and O6 of guanine. O6-methylguanine mispairs with thymine causing G-to-A transitions. Repair: MGMT (a suicide enzyme that removes the alkyl group irreversibly) and BER (for N7)"]','A','MGMT promoter methylation (epigenetic silencing) in glioblastoma predicts better response to temozolomide because DNA damage cannot be repaired. MGMT is a suicide enzyme - it accepts the methyl group permanently and is inactivated, requiring new protein synthesis.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','hard','flashcard','What are the differences between euchromatin and heterochromatin and how is chromatin remodelling achieved?','["Euchromatin: loosely packed, transcriptionally active, acetylated histones. Heterochromatin: tightly packed, transcriptionally silent, methylated histones (H3K9me3) and methylated DNA (CpG). Chromatin remodelling: histone acetyltransferases (HATs, activate) vs histone deacetylases (HDACs, silence); SWI/SNF complexes (ATP-dependent remodelling)"]','A','Histone acetylation neutralises positive charge on lysine residues, relaxing DNA-histone interaction. HDAC inhibitors (vorinostat, romidepsin) are used in T-cell lymphomas. DNA methylation at CpG islands silences tumour suppressor genes in cancer. Imprinting uses methylation to silence one parental allele.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - DNA','hard','flashcard','What are the molecular features of trinucleotide repeat expansion diseases?','["Type 1 (coding/polyglutamine, CAG): Huntington disease, SCA, SBMA - toxic gain-of-function protein. Type 2 (non-coding, CG-rich, causes methylation): Fragile X (CGG in FMR1 5-UTR, FMRP loss), Friedreich ataxia (GAA in FXN intron 1, frataxin loss). Both show anticipation (expansion grows with generations)."]','A','Huntington disease: more than 36 CAG repeats in HTT exon 1 leads to polyglutamine protein aggregation. Fragile X: more than 200 CGG repeats causes FMR1 methylation and silencing, loss of FMRP (regulates synaptic mRNA translation), intellectual disability. Anticipation more pronounced via maternal transmission in Fragile X.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','easy','flashcard','What are the three types of RNA and their roles in protein synthesis?','["mRNA (messenger RNA): carries genetic information from DNA to ribosome as codons. tRNA (transfer RNA): adaptor molecule that carries amino acids and recognises codons via anticodon. rRNA (ribosomal RNA): structural and catalytic component of ribosomes (peptidyl transferase activity in 23S/28S rRNA)"]','A','rRNA is the most abundant RNA in the cell. tRNA is the smallest RNA (approximately 76-90 nt). mRNA is the least abundant but most diverse. All RNA species are made by transcription of DNA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','easy','flashcard','What are the three stop codons and the single start codon in the genetic code?','["Stop codons: UAA, UAG, UGA (mnemonic: U Are Awful, U Are Gone, U Go Away). Start codon: AUG (methionine; fMet in prokaryotes). The genetic code is universal, degenerate (multiple codons per amino acid), non-overlapping, and read in triplets."]','A','The genetic code is nearly universal with minor exceptions (e.g., mitochondrial code). Degeneracy is concentrated in the third (wobble) position. Nonsense mutations introduce premature stop codons; missense mutations change the amino acid; silent mutations do not change the amino acid.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','easy','flashcard','What are the key steps of eukaryotic mRNA processing (pre-mRNA to mature mRNA)?','["1. 5-prime 7-methylguanosine cap addition (protects from exonucleases, aids ribosome binding). 2. 3-prime poly-A tail addition (approximately 200 A residues, aids stability and nuclear export). 3. Splicing (removal of introns by spliceosome, joining exons)"]','A','The spliceosome is a ribonucleoprotein complex (snRNPs: U1, U2, U4, U5, U6 snRNAs + proteins). Splice site consensus: 5-prime GU...AG 3-prime (GT-AG rule). Alternative splicing generates multiple proteins from one gene. Mutations at splice sites cause disease (e.g., some beta-thalassaemia mutations).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','flashcard','What are the differences between prokaryotic and eukaryotic RNA polymerases?','["Prokaryotes: one RNA polymerase (with sigma factor for promoter recognition). Eukaryotes: three nuclear RNA polymerases: Pol I (rRNA, 28S, 18S, 5.8S), Pol II (mRNA and most snRNA/snoRNA), Pol III (tRNA, 5S rRNA, small RNAs). Pol II is inhibited by alpha-amanitin (Amanita phalloides mushroom toxin)"]','A','Alpha-amanitin poisoning (death cap mushroom) inhibits Pol II > Pol III. mRNA synthesis is blocked leading to liver failure. Rifampin inhibits bacterial RNA polymerase (targets beta-subunit). Actinomycin D intercalates DNA and inhibits all RNA polymerases.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','flashcard','What are the three sites on the ribosome during translation and how does elongation proceed?','["A site (aminoacyl-tRNA entry), P site (peptidyl-tRNA, growing chain), E site (exit, empty tRNA leaves). Elongation: aminoacyl-tRNA enters A site (EF-Tu-GTP), peptide bond formed by peptidyl transferase (23S/28S rRNA ribozyme activity), translocation (EF-G-GTP moves ribosome 3-prime by one codon, A-to-P-to-E shift)"]','A','Each elongation step requires GTP hydrolysis. Diphtheria toxin ADP-ribosylates EF-2 (eEF-2), inhibiting translocation and killing the cell. Aminoglycoside antibiotics cause misreading of mRNA at the A site.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','flashcard','What are common post-translational modifications (PTMs) and their functional significance?','["Phosphorylation (serine/threonine/tyrosine - regulates enzyme activity/signalling), glycosylation (N-linked in ER, O-linked in Golgi - protein folding and trafficking), ubiquitination (proteasomal degradation or signalling), acetylation (histones - chromatin regulation), hydroxylation (proline/lysine in collagen - requires vitamin C)"]','A','N-linked glycosylation occurs co-translationally in the ER lumen (Asn-X-Ser/Thr sequon). O-linked glycosylation occurs in the Golgi (Ser/Thr residues). GPI anchor deficiency in PNH (paroxysmal nocturnal haemoglobinuria) causes complement-mediated haemolysis.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','medium','flashcard','What is RNA interference (RNAi) and how do siRNA and miRNA differ?','["RNAi is sequence-specific gene silencing by small non-coding RNAs via the RISC complex. siRNA: exogenous, perfectly complementary to target, causing mRNA cleavage (slicing). miRNA: endogenous, imperfect complementarity to 3-prime UTR, causing translational repression and mRNA destabilisation. Both processed by Dicer."]','A','miRNAs regulate approximately 60% of human protein-coding genes. Dysregulation is common in cancer (e.g., miR-21 is an oncomiR; miR-34 is a tumour suppressor regulated by p53). RNAi is used in emerging therapeutics (e.g., patisiran for transthyretin amyloidosis).','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','hard','flashcard','What is the lac operon and how does it serve as a model for prokaryotic gene regulation?','["The lac operon encodes genes for lactose metabolism (lacZ, lacY, lacA). It is negatively regulated by a repressor (binds operator when lactose is absent) and positively regulated by CAP-cAMP (activated when glucose is low). Both inducer (allolactose) and low glucose must be present for maximal expression - catabolite repression model."]','A','Allolactose (lactose metabolite) binds the lac repressor causing a conformational change that releases the operator, allowing transcription to begin. CAP + cAMP bends DNA and recruits RNA polymerase. In eukaryotes there are no operons; gene regulation is achieved via enhancers, silencers, and chromatin remodelling.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','hard','flashcard','How do protein-sorting signals direct newly synthesised proteins to their correct cellular destination?','["Signal peptide (N-terminal hydrophobic sequence) to ER (co-translational insertion via SRP); KDEL sequence (C-terminus) to ER retention; mannose-6-phosphate (M6P) to lysosomes; nuclear localisation signal (NLS, rich in Lys/Arg) to nucleus; mitochondrial targeting sequence (N-terminal amphipathic helix) to mitochondria"]','A','I-cell disease (mucolipidosis II): deficiency of GlcNAc-1-phosphotransferase causes failure to add M6P to lysosomal enzymes, so enzymes are secreted extracellularly instead of reaching lysosomes, causing severe lysosomal dysfunction. Diagnose by elevated lysosomal enzymes in serum with deficiency in cells.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Molecular Biology - Gene Expression','hard','flashcard','What are the mechanisms of antibiotic inhibition of bacterial protein synthesis?','["30S subunit inhibitors: aminoglycosides (misreading, bactericidal), tetracyclines (block aminoacyl-tRNA binding, bacteriostatic). 50S subunit inhibitors: macrolides/erythromycin (block translocation), chloramphenicol (inhibits peptidyl transferase), linezolid (blocks initiation), clindamycin (blocks translocation)"]','A','Mnemonic for 30S inhibitors: aminoglycosides and tetracyclines. 50S: macrolides, erythromycin, chloramphenicol, clindamycin, linezolid. Chloramphenicol inhibits 50S peptidyl transferase (same target as mitochondrial ribosomes causing grey baby syndrome due to immature glucuronosyltransferase in neonates).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','easy','flashcard','What are the five protein complexes of the electron transport chain and their functions?','["Complex I (NADH dehydrogenase, pumps 4H+), Complex II (succinate dehydrogenase, does NOT pump H+, contains FAD), Complex III (cytochrome bc1 complex, pumps 4H+), Complex IV (cytochrome c oxidase, pumps 4H+, reduces O2 to H2O), Complex V (ATP synthase, uses proton gradient to synthesise ATP)"]','A','Electrons from NADH enter at Complex I; electrons from FADH2 enter at Complex II. Mobile carriers: ubiquinone (CoQ) shuttles electrons from I/II to III; cytochrome c shuttles electrons from III to IV. Net: 2.5 ATP/NADH, 1.5 ATP/FADH2 (updated P/O ratios).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','easy','flashcard','What is the chemiosmotic theory (Mitchell hypothesis) of ATP synthesis?','["Electron transport drives protons (H+) from the mitochondrial matrix to the intermembrane space, creating an electrochemical gradient (proton-motive force). Protons flow back through ATP synthase (Complex V/F0F1), driving rotation of the F0 c-ring, which rotates the gamma subunit in F1, catalysing ADP + Pi to ATP"]','A','The proton-motive force has two components: delta-psi (membrane potential, approximately 180 mV, dominant) and delta-pH. Uncouplers (e.g., DNP, FCCP) collapse the gradient as H+ carriers, dissipating energy as heat instead of ATP. Brown adipose tissue uses UCP-1 (thermogenin) for physiological uncoupling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','easy','flashcard','What is the total ATP yield from complete oxidation of one glucose molecule?','["Approximately 30-32 ATP: 2 ATP (glycolysis substrate-level) + 2 ATP (TCA substrate-level from GTP) + approximately 26 ATP (from oxidative phosphorylation of 10 NADH x 2.5 + 2 FADH2 x 1.5)"]','A','Updated P/O ratios: 2.5 ATP/NADH, 1.5 ATP/FADH2 (revised from old values of 3 and 2). The actual yield varies depending on the shuttle used to transfer cytosolic NADH (malate-aspartate shuttle gives 2.5; glycerol-3-P shuttle gives 1.5 ATP per cytosolic NADH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','flashcard','Which compounds inhibit specific complexes of the ETC and what are the clinical consequences?','["Complex I: rotenone, amytal (barbiturates), metformin. Complex II: carboxin. Complex III: antimycin A. Complex IV: cyanide (binds Fe3+ in cytochrome a3), carbon monoxide (binds Fe2+), hydrogen sulfide, azide. Complex V: oligomycin. All inhibitors cause decreased ATP, increased NADH, and lactic acidosis."]','A','Cyanide poisoning inhibits Complex IV so cells cannot use O2 (histotoxic hypoxia). O2 saturation is normal but cells cannot use it. Treat with hydroxocobalamin or nitrites (form methaemoglobin which competes with cytochrome oxidase for cyanide) plus thiosulfate. CO has 250 times higher affinity for haemoglobin than O2.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','flashcard','What is the function of uncoupling protein 1 (UCP-1/thermogenin) in brown adipose tissue?','["UCP-1 creates a proton leak across the inner mitochondrial membrane, dissipating the proton gradient as heat rather than ATP synthesis. This is the basis of non-shivering thermogenesis, important in neonates and hibernating animals."]','A','Brown adipose tissue (BAT) is rich in mitochondria and is innervated by the sympathetic nervous system. Activation by cold causes noradrenaline release, beta3 receptor activation, lipolysis, and fatty acids then activate UCP-1. BAT is present in human neonates and around the aorta/neck in adults.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','flashcard','What are reactive oxygen species (ROS) and how does the cell defend against them?','["ROS (superoxide O2 radical, hydrogen peroxide H2O2, hydroxyl radical) are generated as by-products of the ETC (Complex I and III), phagocytes (NADPH oxidase), and radiation. Antioxidant defences: superoxide dismutase (SOD, converts superoxide to H2O2), catalase (H2O2 to H2O + O2), glutathione peroxidase (H2O2 to H2O, requires GSH, replenished by NADPH from PPP)"]','A','Chronic granulomatous disease (CGD): NADPH oxidase deficiency causes phagocytes unable to generate superoxide, impairing killing of catalase-positive organisms (S. aureus, Aspergillus). G6PD deficiency impairs NADPH production, reducing glutathione, causing haemolytic anaemia with oxidant drugs.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','medium','flashcard','What is the role of creatine phosphate (phosphocreatine) in muscle energy metabolism?','["Phosphocreatine is a high-energy phosphate buffer in muscle and brain. During intense activity, creatine kinase rapidly transfers the phosphate group to ADP to form ATP, bridging the gap before oxidative phosphorylation can accelerate. PCr/Cr ratio reflects cellular energy status."]','A','Phosphocreatine regenerates ATP within seconds, faster than glycolysis. It is depleted within approximately 10 seconds of maximal exercise. Creatine supplementation increases PCr stores, enhancing short-burst performance. Creatinine (urinary excretion product of creatine/PCr) is used to estimate GFR.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','hard','flashcard','What is the significance of the malate-aspartate shuttle vs the glycerol-3-phosphate shuttle for cytosolic NADH entry into mitochondria?','["Malate-aspartate shuttle (liver, heart, kidney): cytosolic NADH yields malate which crosses the inner membrane and regenerates mitochondrial NADH, giving 2.5 ATP. Glycerol-3-phosphate shuttle (brain, muscle): cytosolic NADH gives electrons to FAD at Complex II level, yielding FADH2 and 1.5 ATP. The malate-aspartate shuttle is more efficient."]','A','The inner mitochondrial membrane is impermeable to NAD+/NADH, necessitating these shuttle systems to transfer reducing equivalents. The malate-aspartate shuttle requires transporters (malate-alpha-KG, aspartate-glutamate) and transaminases on both sides of the membrane.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','hard','flashcard','What are the features of mitochondrial DNA (mtDNA) and mitochondrial diseases?','["mtDNA: circular, 16,569 bp, 37 genes (13 OXPHOS subunits, 22 tRNAs, 2 rRNAs), maternally inherited, no introns, high mutation rate (no histones, near ROS source). Mitochondrial diseases: heteroplasmy, mitochondrial threshold effect, maternal inheritance, high-energy tissues most affected"]','A','Examples: MELAS (mitochondrial encephalomyopathy, lactic acidosis, stroke-like episodes - m.3243A>G in MT-TL1), MERRF (myoclonic epilepsy with ragged-red fibres - MT-TK), Leber hereditary optic neuropathy (LHON - Complex I subunit mutations). Ragged-red fibres (Gomori trichrome) represent mitochondrial proliferation.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Energy Metabolism & Oxidative Phosphorylation','hard','flashcard','What is the mechanism of action of 2,4-dinitrophenol (DNP) as a metabolic uncoupler?','["DNP is a lipid-soluble weak acid that carries protons across the inner mitochondrial membrane, bypassing ATP synthase. It collapses the proton gradient so the ETC runs without restraint, NADH/FADH2 is oxidised rapidly, and energy is released as heat instead of ATP, increasing metabolic rate and O2 consumption with no net ATP gain."]','A','DNP was used as a weight-loss drug in the 1930s but caused hyperthermia and deaths. It is still available illegally online. The mechanism mimics physiological uncoupling by UCP-1 in BAT. Body temperature can reach fatal levels as all energy is released as heat.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','easy','flashcard','What are the metabolic effects of insulin and what is its mechanism of action?','["Insulin (released by pancreatic beta-cells in response to high blood glucose) promotes glucose uptake (GLUT4 translocation in muscle/fat), glycogen synthesis, glycolysis, fatty acid synthesis, and protein synthesis. Inhibits gluconeogenesis, glycogenolysis, lipolysis, and ketogenesis."]','A','Insulin binds its receptor tyrosine kinase causing autophosphorylation, IRS-1/IRS-2 activation, PI3K, Akt/PKB, and GLUT4 translocation. Also activates MAP kinase pathway for cell growth. Insulin is anabolic: it BUILDS up glycogen, lipids, and protein.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','easy','flashcard','What are the metabolic effects of glucagon and what is its mechanism of action?','["Glucagon (released by pancreatic alpha-cells during fasting/low glucose) stimulates glycogenolysis (phosphorylase activation), gluconeogenesis, fatty acid oxidation, and ketogenesis. Inhibits glycolysis (lowers F2,6-BP), glycogen synthesis, and fatty acid synthesis."]','A','Glucagon binds GPCR (Gs) causing adenylyl cyclase activation, increased cAMP, PKA activation, phosphorylation and activation of phosphorylase kinase, and activation of glycogen phosphorylase. Also phosphorylates PFK-2/FBPase-2 bifunctional enzyme lowering F2,6-BP, which inhibits PFK-1. Glucagon is catabolic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','flashcard','What are the key metabolic events in the well-fed (absorptive) state?','["High glucose causes insulin release, glucose uptake by muscle and fat (GLUT4); liver performs glycolysis, glycogen synthesis, and fatty acid synthesis; muscle performs protein synthesis and glycogen synthesis; adipose tissue performs lipogenesis (VLDL-derived FA uptake via lipoprotein lipase) and fatty acid esterification to TG"]','A','In the absorptive state the body is in anabolic mode with glucose as the primary fuel for all tissues. Excess glucose is stored as glycogen (liver 100g, muscle 400g) and converted to fat in the liver (de novo lipogenesis), then packaged as VLDL and stored in adipose. RQ approaches 1.0.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','flashcard','What metabolic changes occur during prolonged fasting (more than 24 hours)?','["Glycogen stores depleted by 24 hours. Liver gluconeogenesis maintains blood glucose (from amino acids, lactate, glycerol). Adipose lipolysis provides FFAs as fuel for muscle and liver. Hepatic ketogenesis increases. Brain adapts to use ketones after approximately 3 days. Muscle catabolism provides gluconeogenic amino acids."]','A','Metabolic priority during fasting: (1) maintain blood glucose for RBCs and brain; (2) spare protein by shifting to fat and ketone utilisation. Cortisol, glucagon, and adrenaline rise; insulin falls. RQ drops toward 0.7 (fat burning). After weeks, brain uses ketones for approximately 70% of its energy needs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','flashcard','What is the role of AMPK (AMP-activated protein kinase) in metabolic regulation?','["AMPK is the cellular energy sensor activated by high AMP:ATP ratio (energy depletion). When activated: stimulates fatty acid oxidation (inhibits ACC reducing malonyl-CoA and activating CAT-I), stimulates glucose uptake (GLUT4 translocation), inhibits fatty acid synthesis, inhibits cholesterol synthesis (inhibits HMG-CoA reductase), inhibits glycogen synthesis"]','A','AMPK mimics exercise and fasting effects. Metformin activates AMPK via Complex I inhibition causing increased AMP. Thiazolidinediones (TZDs) also activate AMPK indirectly. AMPK phosphorylates and inhibits ACC, reducing malonyl-CoA and de-suppressing CAT-I for beta-oxidation.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','flashcard','How does cortisol affect metabolism?','["Cortisol (glucocorticoid released in stress/fasting) stimulates gluconeogenesis (induces PEPCK and G6Pase), promotes muscle protein catabolism (provides gluconeogenic amino acids), inhibits peripheral glucose uptake, stimulates lipolysis (permissive for glucagon/catecholamines), and is anti-inflammatory (inhibits PLA2, reduces prostaglandin synthesis)"]','A','Cushing syndrome (excess cortisol): central obesity (buffalo hump, moon face), hyperglycaemia (steroid diabetes), muscle wasting, osteoporosis, immunosuppression, thin skin, striae, hypertension. Cortisol also induces PNMT in adrenal medulla (required for epinephrine synthesis from norepinephrine).','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','medium','flashcard','What are the metabolic roles of the major tissues (liver, muscle, adipose, brain) in the fasting state?','["Liver: gluconeogenesis (primary glucose supplier), glycogenolysis, ketogenesis, urea synthesis. Muscle: uses FFAs and ketones; provides alanine and glutamine as gluconeogenic substrates; cannot release glucose (lacks G6Pase). Adipose: lipolysis releases FFAs and glycerol. Brain: primarily glucose; adapts to use ketones in prolonged fasting."]','A','The Cori cycle: muscle glycolysis yields lactate which goes to liver gluconeogenesis which yields glucose back to muscle. The glucose-alanine cycle: muscle transamination yields alanine which goes to liver gluconeogenesis and urea cycle. These cycles allow non-hepatic tissues to fuel hepatic glucose production during fasting.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','hard','flashcard','What is the biochemical basis of insulin resistance and type 2 diabetes mellitus?','["In obesity, excess FFAs and ceramides activate serine kinases (IKKbeta, JNK) that phosphorylate IRS-1 on serine residues. IRS-1 cannot then be tyrosine-phosphorylated by the insulin receptor so downstream signalling (PI3K-Akt) is impaired, causing reduced GLUT4 translocation and failure to suppress gluconeogenesis."]','A','Ectopic lipid deposition (liver steatosis, intramyocellular lipid) and inflammatory cytokines (TNF-alpha, IL-6 from adipose macrophages) also impair insulin signalling. Beta-cell exhaustion occurs after prolonged overproduction of insulin. Treatment: lifestyle changes, metformin (AMPK), GLP-1 agonists, SGLT2 inhibitors.','universal',true,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','hard','flashcard','What are the metabolic consequences of diabetic ketoacidosis (DKA) and its biochemical basis?','["DKA (type 1 DM): absolute insulin deficiency causes unrestrained glucagon, maximal gluconeogenesis and glycogenolysis (hyperglycaemia), unrestrained lipolysis, excess acetyl-CoA, ketogenesis (acetoacetate, beta-hydroxybutyrate), metabolic acidosis, osmotic diuresis, dehydration, and electrolyte loss."]','A','Anion gap metabolic acidosis: Na+ - (Cl- + HCO3-) > 12. Kussmaul breathing (deep, rapid) compensates for acidosis. Fruity breath from acetone. Serum K+ may appear high (K+ shifts out of cells in acidosis) but total body K+ is depleted. Treatment: IV fluids, insulin, K+ replacement (not before checking serum K+), treat precipitant.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Metabolic Integration & Hormonal Control','hard','flashcard','What is the role of mTOR in nutrient sensing and anabolic signalling?','["mTOR complex 1 (mTORC1) integrates signals from nutrients (amino acids, glucose), growth factors (insulin/IGF-1 via PI3K-Akt), and energy status (AMPK inhibits mTORC1). When active, mTORC1 promotes protein synthesis (phosphorylates S6K1 and 4E-BP1), lipid synthesis, and inhibits autophagy."]','A','mTOR is hyperactive in many cancers (PI3K/PTEN/Akt pathway). Rapamycin (sirolimus) inhibits mTORC1 by binding FKBP12; used as immunosuppressant and in cancer. Amino acids (especially leucine) activate mTORC1 via Rag GTPases and Ragulator complex at the lysosomal surface. AMPK opposes mTORC1 by phosphorylating Raptor and TSC2.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','easy','flashcard','What is phenylketonuria (PKU) and how is it managed?','["PKU: autosomal recessive deficiency of phenylalanine hydroxylase (PAH, requires BH4 cofactor) causing accumulation of phenylalanine and its metabolites (phenylpyruvate, phenylacetate, phenyllactate). Features: intellectual disability, musty/mousy odour, fair skin/hair/eyes, seizures. Detected on newborn screening. Management: phenylalanine-restricted diet plus sapropterin (BH4) for BH4-responsive PKU."]','A','Normal PAH converts Phe to Tyr. Without PAH, Phe is transaminated to phenylpyruvate. Early dietary treatment is essential to prevent brain damage. Maternal PKU: untreated PKU in pregnancy causes teratogenicity (microcephaly, congenital heart disease) in the baby even if the baby is heterozygous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','easy','flashcard','What is classic galactosaemia and what are its clinical features?','["Autosomal recessive deficiency of galactose-1-phosphate uridyltransferase (GALT) causing accumulation of galactose-1-phosphate and galactitol (via aldose reductase). Features: neonatal jaundice, hepatomegaly, E. coli sepsis (galactose impairs neutrophil function), cataracts (galactitol deposition), intellectual disability, ovarian failure. Treatment: galactose-free diet (no lactose/dairy)."]','A','Distinguish from galactokinase deficiency (milder, only cataracts and galactosaemia). GALT deficiency is detected on newborn screening. Galactitol accumulates in the lens causing cataracts (osmotic damage). E. coli neonatal sepsis in a breast-fed neonate should prompt consideration of galactosaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','easy','flashcard','What is the general approach to diagnosing an inborn error of metabolism (IEM) in a neonate?','["Suspect IEM in a neonate who was well at birth but deteriorates: encephalopathy, poor feeding, vomiting, metabolic acidosis, or unusual odour. Initial workup: blood glucose, lactate, ammonia, blood gas, urine organic acids, plasma amino acids, acylcarnitine profile (dried blood spot). Newborn screening (tandem MS) detects many IEMs before symptoms."]','A','Clues: metabolic acidosis (organic acidaemias), hyperammonaemia (urea cycle disorders), hypoglycaemia (fatty acid oxidation disorders, GSD). Odour clues: maple syrup (MSUD), musty (PKU), sweaty feet (isovaleric acidaemia), cabbage (tyrosinaemia type I). Tandem mass spectrometry can screen for more than 30 IEMs simultaneously.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','flashcard','What are the glycogen storage diseases (GSDs) and how do they differ?','["Type I (von Gierke): G6Pase deficiency, severe hypoglycaemia, hepatomegaly, lactic acidosis, hyperuricaemia. Type II (Pompe): lysosomal acid alpha-glucosidase (GAA) deficiency, glycogen in lysosomes, cardiomegaly and myopathy. Type III (Cori): debranching enzyme deficiency, limit dextrin accumulation. Type V (McArdle): muscle phosphorylase deficiency, exercise intolerance, myoglobinuria, no lactate rise with exercise."]','A','Mnemonic for Type V McArdle: muscles cannot mobilise glycogen so no lactate on forearm exercise test (ischaemic exercise test). Pompe disease is treated with enzyme replacement therapy (alglucosidase alfa). Von Gierke is treated with uncooked cornstarch (slow glucose release) and avoidance of fasting.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','flashcard','What are lysosomal storage diseases and give three examples with their enzyme defects?','["Lysosomal storage diseases result from deficiency of lysosomal hydrolases (or their activators/transporters) causing substrate accumulation within lysosomes. Examples: Gaucher disease (glucocerebrosidase deficiency, glucocerebroside in macrophages, hepatosplenomegaly, bone marrow infiltration), Tay-Sachs (hexosaminidase A deficiency, GM2 ganglioside, neurodegeneration, cherry-red spot), Niemann-Pick type A/B (sphingomyelinase deficiency, sphingomyelin, hepatosplenomegaly)"]','A','Most are autosomal recessive. Cherry-red spot seen in: Tay-Sachs, Niemann-Pick type A, Sandhoff, and central retinal artery occlusion. Treatment: enzyme replacement therapy (Gaucher type 1, Pompe, Fabry, MPS I/II/VI), substrate reduction therapy, haematopoietic stem cell transplant.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','flashcard','What are the mucopolysaccharidoses (MPS) and what is the underlying biochemical defect?','["MPS: deficiency of lysosomal enzymes that degrade glycosaminoglycans (GAGs: dermatan sulfate, heparan sulfate, keratan sulfate, chondroitin sulfate) causing GAG accumulation in tissues. Features: coarse facies, corneal clouding, hepatosplenomegaly, skeletal dysostosis, cardiac valve disease, intellectual disability (in some types)."]','A','Hurler syndrome (MPS I): alpha-L-iduronidase deficiency, severe (corneal clouding + neurodegeneration). Hunter syndrome (MPS II): iduronate sulfatase, X-linked, no corneal clouding. Sanfilippo (MPS III): predominantly neurological. Morquio (MPS IV): keratan sulfate, normal intelligence, atlantoaxial instability. Treatment: enzyme replacement therapy, HSCT.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','medium','flashcard','What is maple syrup urine disease (MSUD) and which amino acids accumulate?','["MSUD: autosomal recessive deficiency of branched-chain alpha-keto acid dehydrogenase (BCKDH; requires TPP/thiamine), causing accumulation of branched-chain amino acids (leucine, isoleucine, valine) and their alpha-keto acid derivatives. Features: sweet maple syrup odour of urine, encephalopathy, seizures, cerebral oedema. Leucine is most toxic."]','A','The BCKDH enzyme complex is structurally analogous to PDH and alpha-KGDH - all three require TPP, lipoic acid, CoA, FAD, and NAD+ as cofactors. Treatment: restrict BCAAs, high-calorie diet, thiamine supplementation for thiamine-responsive variant. Liver transplant can cure classic MSUD.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','hard','flashcard','What is Fabry disease and what is its biochemical basis?','["Fabry disease: X-linked deficiency of alpha-galactosidase A causing accumulation of globotriaosylceramide (Gb3) in vascular endothelium, heart, kidneys, and peripheral nerves. Features: acroparaesthesias (burning pain in hands/feet), angiokeratomas (dark skin lesions), hypohidrosis, corneal whorling (verticillata), progressive renal failure, cardiomyopathy, stroke. Treatment: enzyme replacement therapy (agalsidase alfa/beta), migalastat (pharmacological chaperone)"]','A','Fabry disease is X-linked so males are fully affected (hemizygous); females can be symptomatic due to X-inactivation. It is the second most common lysosomal storage disease after Gaucher disease. Gb3 accumulation in renal podocytes causes focal segmental glomerulosclerosis pattern leading to CKD.','universal',false,'{year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','hard','flashcard','What are the urea cycle disorders and which is most common? How is hyperammonaemia managed?','["Most common urea cycle disorder: OTC (ornithine transcarbamylase) deficiency, X-linked; others are autosomal recessive (CPS-I, ASS, ASL, arginase deficiency). Features: hyperammonaemia causing cerebral oedema, encephalopathy, vomiting. Neonatal presentation: lethargy, poor feeding, respiratory alkalosis then acidosis."]','A','Management: (1) stop protein intake acutely; (2) provide high-calorie dextrose to suppress catabolism; (3) nitrogen scavengers - sodium benzoate (conjugates glycine to hippurate, excreted) and sodium phenylbutyrate/phenylacetate (conjugates glutamine); (4) arginine supplementation (all except arginase deficiency); (5) dialysis for severe cases; (6) liver transplant (curative). OTC deficiency in carrier females: protein intolerance, episodic confusion.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Biochemistry & Genetics','Biochemistry','Inborn Errors of Metabolism','hard','flashcard','What is Wilson disease and what is the biochemical defect?','["Wilson disease: autosomal recessive deficiency of ATP7B (copper-transporting ATPase in hepatocytes) causing failure to incorporate copper into caeruloplasmin and failure to excrete copper in bile. Copper accumulates in liver, brain, kidneys, and eyes. Features: liver disease (hepatitis to cirrhosis), neuropsychiatric symptoms (tremor, dysarthria, behavioural change), Kayser-Fleischer rings (copper deposits in Descemet membrane), Fanconi syndrome (renal tubular dysfunction)."]','A','Diagnosis: low serum caeruloplasmin, low serum copper but high free copper, high 24-hour urinary copper, liver biopsy (high copper). Kayser-Fleischer rings seen on slit-lamp examination. Treatment: D-penicillamine or trientine (copper chelators), zinc (inhibits copper absorption by inducing metallothionein), liver transplant for fulminant failure.','universal',true,'{year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Biochemistry 7th Ed');
